{
  "status": "SUPPORTED",
  "task_summary": "Find parts in storage, assemble them on the workbench, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "storage_structure",
        "entity_kind": "REGION",
        "function": "holds hidden components and fasteners",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "cabinet",
          "drawer"
        ],
        "required_properties": [
          "enclosed",
          "openable"
        ]
      },
      {
        "id": "component",
        "entity_kind": "OBJECT",
        "function": "structural part to be assembled",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "part",
          "piece",
          "module"
        ],
        "required_properties": [
          "compatible_with_workpiece"
        ]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "hardware used to join parts",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut"
        ],
        "required_properties": [
          "threaded",
          "secure"
        ]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "item being fastened",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "device",
          "object",
          "assembly"
        ],
        "required_properties": [
          "has_connection_point"
        ]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "implement used to drive fastener",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "driver"
        ],
        "required_properties": [
          "manipulatable"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "compatibility_check",
        "relation": "compatible_with",
        "participant_roles": [
          "component",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "assembly_connection",
        "relation": "fastens_to",
        "participant_roles": [
          "fastener",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "final_placement",
        "relation": "placed_on",
        "participant_roles": [
          "tool",
          "workbench"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_storage",
        "operation": "inspect_region",
        "participant_roles": [
          "storage_structure"
        ,
          "robot_arm"
        ],
        "operation_count": 2
      },
      {
        "id": "perform_fastening",
        "operation": "apply_fastener",
        "participant_roles": [
          "tool",
          "fastener",
          "workpiece"
        ],
        "operation_count": 1
      },
      {
        "id": "return_tool",
        "operation": "place_object",
        "participant_roles": [
          "tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "storage_structure": [
        {
          "label": "cabinet",
          "visual_description": "blue boxy unit behind table with handle"
        },
        {
          "label": "drawers",
          "visual_description": "two blue drawers under table surface"
        }
      ],
      "component": [
        {
          "label": "yellow_object",
          "visual_description": "yellow rectangular item on black mat on table"
        }
      ],
      "workpiece": [
        {
          "label": "black_mat_area",
          "visual_description": "dark rectangular area on table where workpiece might be"
        }
      ],
      "tool": [
        {
          "label": "robot_end_effector",
          "visual_description": "white robotic arm segments"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "blue cabinet",
        "visual_description": "tall blue box with vertical handle",
        "reason": "closed container likely holding spare parts or fasteners"
      },
      {
        "id": "drawers",
        "label": "table drawers",
        "visual_description": "two blue drawers under the wooden top",
        "reason": "closed storage unit accessible for retrieving components"
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
